package com.aistock.gateway.statistics;
import com.aistock.common.*;import com.aistock.common.statistics.*;import com.aistock.gateway.*;import com.fasterxml.jackson.databind.*;import jakarta.servlet.http.*;import java.time.Clock;import java.util.*;import org.springframework.http.*;import org.springframework.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping({"/api/v1/admin/statistics","/api/v1/admin/statistics/**"})
public class AdminStatisticsApiProxyController {
 private final UserPublicClient user;private final MarketPublicClient market;private final ForecastPublicClient prediction;private final SchedulerPublicClient scheduler;private final StatisticsAdminAccess access;private final HttpStatisticsCollector http;private final ObjectMapper mapper;private final Clock clock;
 public AdminStatisticsApiProxyController(UserPublicClient user,MarketPublicClient market,ForecastPublicClient prediction,SchedulerPublicClient scheduler,StatisticsAdminAccess access,HttpStatisticsCollector http,ObjectMapper mapper,Clock clock){this.user=user;this.market=market;this.prediction=prediction;this.scheduler=scheduler;this.access=access;this.http=http;this.mapper=mapper;this.clock=clock;}
 @RequestMapping public ResponseEntity<byte[]> get(HttpServletRequest r,HttpServletResponse s,@RequestParam MultiValueMap<String,String> q)throws java.io.IOException{
  s.setHeader("Cache-Control","no-store");String path=r.getRequestURI();if(!"GET".equals(r.getMethod())||!ProxyHeaderPolicy.statisticsPath(path))throw new BusinessException("RESOURCE_NOT_FOUND","接口不存在",HttpStatus.NOT_FOUND);access.requireAdmin(r);
  if(path.endsWith("/http")){StatisticsQuery.none(q);return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).cacheControl(CacheControl.noStore()).body(mapper.writeValueAsBytes(ApiResponse.success(http.snapshot(clock.instant()),TraceIds.normalize(r.getHeader("X-Trace-Id")))));}
  boolean isMarket=path.endsWith("/market");StatisticsQuery.window(q,clock,isMarket?Set.of("page","size"):Set.of());if(isMarket){StatisticsQuery.page(q);StatisticsQuery.size(q);}var query=new LinkedHashMap<String,String>();q.forEach((k,v)->query.put(k,v.get(0)));var headers=ProxyHeaderPolicy.request(r);var relative=path.substring(8);
  try{ResponseEntity<byte[]> reply=switch(path.substring(path.lastIndexOf('/')+1)){case "users"->user.get(relative,query,headers);case "market"->market.get(relative,query,headers);case "predictions"->prediction.get(relative,query,headers);case "tasks"->scheduler.get(relative,q,headers);default->throw unavailable();};
   if(reply==null||reply.getBody()==null||reply.getBody().length>262144)throw unavailable();if(!reply.getStatusCode().is2xxSuccessful())throw upstream(reply.getStatusCode().value(),reply.getBody());
   var node=mapper.readTree(reply.getBody());if(node==null||!"OK".equals(node.path("code").asText())||!node.path("data").isObject())throw unavailable();return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).cacheControl(CacheControl.noStore()).body(reply.getBody());
  }catch(feign.FeignException e){throw upstream(e.status(),e.content());}catch(BusinessException e){throw e;}catch(RuntimeException|java.io.IOException e){throw unavailable();}
 }
 private BusinessException upstream(int status,byte[] bytes){if(status==401)return new BusinessException("AUTH_REQUIRED","请重新登录",HttpStatus.UNAUTHORIZED);if(status==403)return new BusinessException("ACCESS_DENIED","仅管理员可以查看统计",HttpStatus.FORBIDDEN);try{if(bytes.length<=262144){var n=mapper.readTree(bytes);if(status==400&&n!=null&&"STATISTICS_QUERY_INVALID".equals(n.path("code").asText()))return StatisticsQuery.invalid();if(status==503&&n!=null&&"USER_SERVICE_UNAVAILABLE".equals(n.path("code").asText()))return new BusinessException("USER_SERVICE_UNAVAILABLE","账号服务暂不可用",HttpStatus.SERVICE_UNAVAILABLE);}}catch(java.io.IOException ignored){}return unavailable();}
 private static BusinessException unavailable(){return new BusinessException("STATISTICS_UNAVAILABLE","本区统计暂不可用，请稍后刷新",HttpStatus.SERVICE_UNAVAILABLE);}
}
